    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-CE1'), N'P26-CE1', N'Suministro de energía eléctrica en la Ciudad de Pachuca', N'rnt-ampliacion', N'Central', 1, N'8.4.2.1', N'DIAGRAMA UNIFILAR Geográfico de red eléctrica para suministro a la ciudad de pachuca', N'Diagrama unifilar geográfico esquemático. DIAGRAMA UNIFILAR Geográfico de red eléctrica para suministro a la ciudad de pachuca.', N'El suministro de energía eléctrica de la Ciudad de Pachuca, capital del estado de Hidalgo depende de red eléctrica en el nivel de tensión de 85 kV que se interconectan hacia las Subestaciones Eléctricas de Distribución: Pachuca, Cubitos, Hidalgo, Actopan, Dos Carlos, Atotonilco y Parque Industrial Reforma, que a su vez sus fuentes principales de alimentación corresponden a dos circuitos en 85 kV desde la SE Apasco hacia Pachuca y un circuito de la SE Tulancingo hacia Parque Industrial Reforma. Dentro de la zona de interés se tienen otro punto de inyección de energía eléctrica que corresponden a dos bancos de transformación de 100 MVA de capacidad de relación 230/85 kV en la SE Parque Industrial Reforma. En la Figura 8.4.2.1 se muestra diagrama unifilar geográfico simplificado.', N'Diagrama unifilar geográfico esquemático: DIAGRAMA UNIFILAR Geográfico de red eléctrica para suministro a la ciudad de pachuca. Proyecto P26-CE1: Suministro de energía eléctrica en la Ciudad de Pachuca.', N'unifilar-geografico-esquematico', N'Diagrama unifilar geográfico esquemático', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-CE1:FIG-8.4.2.1', N'p26-ce1__fig-8-4-2-1__unifilar-geografico-esquematico__diagnostico-contexto.png', N'pam2026-2040/p26-ce1__fig-8-4-2-1__unifilar-geografico-esquematico__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-ce1__fig-8-4-2-1__unifilar-geografico-esquematico__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-ce1/p26-ce1__fig-8-4-2-1__unifilar-geografico-esquematico__diagnostico-contexto.png', 4096, 2164, N'83fcd171d5a00ab285d4364927797e15851abcd0e2a5297a52eff0f97e8d6493', N'leyenda y contexto textual del PAM');
