    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-CE1'), N'P26-CE1', N'Suministro de energía eléctrica en la Ciudad de Pachuca', N'rnt-ampliacion', N'Central', 5, N'8.4.2.5', N'Líneas de transmisión DEL CORREDOR PARQUE INDUSTRIAL REFORMA–CUBITOS–PACHUCA en 85 kV', N'Diagrama técnico. Líneas de transmisión DEL CORREDOR PARQUE INDUSTRIAL REFORMA–CUBITOS–PACHUCA en 85 kV.', N'Por lo anterior, resulta necesario implementar la repotenciación de los tramos subterráneos de las LT en 85 kV Parque Industrial Reforma - 73Q70 –Cubitos y Pachuca – 73T10 - Cubitos, con el objetivo de incrementar su capacidad de transmisión al límite de la Línea de Transmisión aérea que interconecta que corresponde a 133 MVA y así mitigar la problemática identificada, En la Figura 8.4.2.5 se muestra este corredor.', N'Diagrama técnico: Líneas de transmisión DEL CORREDOR PARQUE INDUSTRIAL REFORMA–CUBITOS–PACHUCA en 85 kV. Proyecto P26-CE1: Suministro de energía eléctrica en la Ciudad de Pachuca.', N'diagrama-tecnico', N'Diagrama técnico', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-CE1:FIG-8.4.2.5', N'p26-ce1__fig-8-4-2-5__diagrama-tecnico__diagnostico-contexto.png', N'pam2026-2040/p26-ce1__fig-8-4-2-5__diagrama-tecnico__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-ce1__fig-8-4-2-5__diagrama-tecnico__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-ce1/p26-ce1__fig-8-4-2-5__diagrama-tecnico__diagnostico-contexto.png', 3628, 1780, N'4915e8175abb9565264b7b2e11d2d708559cc99bfd3a3b46af99d71acd388ba1', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-CE1'), N'P26-CE1', N'Suministro de energía eléctrica en la Ciudad de Pachuca', N'rnt-ampliacion', N'Central', 6, N'8.4.2.6', N'DIAGRAMA UNIFILAR DE SUBESTACIÓN eléctrica PARQUE INDUSTRIAL REFORMA.', N'Diagrama unifilar técnico. DIAGRAMA UNIFILAR DE SUBESTACIÓN eléctrica PARQUE INDUSTRIAL REFORMA.', N'Por otro lado, la S.E. Parque Industrial Reforma se compone por un arreglo no normalizado que interconecta un arreglo doble barra con un arreglo en anillo, lo que también reduce la confiabilidad y flexibilidad del sistema ya que ante una libranza o falla en la LT Parque Industrial Reforma - 73Q70 - Cubitos o en la LT Parque Industrial Reforma - 73T20 – Tulancingo en 85 kV, se interrumpe el flujo de potencia proveniente de la SE Pachuca Potencia hacia las SE Cubitos y Tulancingo. En Figura 8.4.2.6 se muestra el diagrama unifilar simplificado de la SE Parque Industrial Reforma, donde se observa que uno de los bancos de transformación para distribución se encuentra conectado a un arreglo en anillo.', N'Diagrama unifilar técnico: DIAGRAMA UNIFILAR DE SUBESTACIÓN eléctrica PARQUE INDUSTRIAL REFORMA. Proyecto P26-CE1: Suministro de energía eléctrica en la Ciudad de Pachuca.', N'unifilar-tecnico', N'Diagrama unifilar técnico', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-CE1:FIG-8.4.2.6', N'p26-ce1__fig-8-4-2-6__unifilar-tecnico__diagnostico-contexto.png', N'pam2026-2040/p26-ce1__fig-8-4-2-6__unifilar-tecnico__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-ce1__fig-8-4-2-6__unifilar-tecnico__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-ce1/p26-ce1__fig-8-4-2-6__unifilar-tecnico__diagnostico-contexto.png', 2220, 1216, N'fa036f4a1ad30a22d30f1548dbece2662ebcb174884ef531070d8ff9449c1728', N'leyenda y contexto textual del PAM');
