    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-OC1'), N'P26-OC1', N'Suministro de energía en la zona metropolitana de Guadalajara.', N'rnt-ampliacion', N'Occidental', 2, N'8.4.3.2', N'INCREMENTO DE FLUJO EN LOS TRANSFORMADORES EN EL PERIODO 2030-2040 EN LA ZMG EN RED ELÉCTRICA COMPLETA', N'Gráfica analítica. INCREMENTO DE FLUJO EN LOS TRANSFORMADORES EN EL PERIODO 2030-2040 EN LA ZMG EN RED ELÉCTRICA COMPLETA.', N'se prevé la ocurrencia de sobrecargas en los bancos de transformación 400/230 kV, 230/69 kV y 400/69 kV, así como en diversas Líneas de Transmisión de 69 kV, incluso bajo condiciones de Red Eléctrica completa. Con base en las proyecciones de crecimiento de demanda, se estima un incremento significativo en los flujos de potencia a través de los Transformadores, alcanzando incrementos del orden del 36% de su capacidad nominal durante el periodo 2030–2040, lo cual describe en cada una de las barras de la Figura 8.4.3.2. En la parte inferior de la barra se muestra, la capacidad esperada para el año 2030 y en la parte superior de la barra, la capacidad esperada para el año 2040, el porcentaje mostrado en cada barra indica el crecimiento esperado. Por lo que se puede apreciar de manera gráfica, las sobrecargas esperadas en cada uno de los elementos los cuales superan su límite (línea roja punteada).', N'Gráfica analítica: INCREMENTO DE FLUJO EN LOS TRANSFORMADORES EN EL PERIODO 2030-2040 EN LA ZMG EN RED ELÉCTRICA COMPLETA. Proyecto P26-OC1: Suministro de energía en la zona metropolitana de Guadalajara..', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-OC1:FIG-8.4.3.2', N'p26-oc1__fig-8-4-3-2__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/p26-oc1__fig-8-4-3-2__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-oc1__fig-8-4-3-2__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-oc1/p26-oc1__fig-8-4-3-2__grafica-analitica__diagnostico-contexto.png', 4096, 2168, N'27f2634ebee955deef1486d11e435489b6097e4c924531e22bca5f41ab104ab1', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-OC1'), N'P26-OC1', N'Suministro de energía en la zona metropolitana de Guadalajara.', N'rnt-ampliacion', N'Occidental', 3, N'8.4.3.3', N'PROBLEMÁTICA DE SOBRECARGAS EN EL PERIODO 2030-2040 EN LA ZMG', N'Gráfica analítica. PROBLEMÁTICA DE SOBRECARGAS EN EL PERIODO 2030-2040 EN LA ZMG.', N'Por otro lado, se espera que ante falla y salida de operación de alguna Línea de Transmisión o banco de transformación, otros elementos superen su capacidad, entre ellos, los transformadores 400/230 de las SE Acatlán, Tesistán y Zapotlanejo, así como en el Transformador 400/69 kV de la SE Tesistán, además, en los Transformadores 230/69 kV de la SE Zapopan, Guadalajara I, Guadalajara Oriente, Acatlán, Guadalajara Norte, Guadalajara II y las Líneas de Transmisión en nivel de tensión de 69 kV El Pinar – 63A20 – Tesistán, La Mojonera – 63A30 – Tesistán, Parque Industrial – 63CO0 – Guadalajara Dos, Zoquipan – 63260 – Guadalajara Norte, La Mojonera – 63470 – El Pinar, Zapopan – 63110 – El Sol, El Pinar – 63920 – Tesistán, Higuerillas – 63150 – Guadalajara I y Guadalajara Industrial – 63OC0 – Higuerillas, lo anterior se muestra en la Figura 8.4.3.3, en donde es posible observar el año en el que se espera se sobrecargue, en Red Eléctrica completa, el equipo descrito en la parte superior, mientras que en la parte inferior se muestra que equipo se espera sobrecargado y en qué año, ante N-1.', N'Gráfica analítica: PROBLEMÁTICA DE SOBRECARGAS EN EL PERIODO 2030-2040 EN LA ZMG. Proyecto P26-OC1: Suministro de energía en la zona metropolitana de Guadalajara..', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-OC1:FIG-8.4.3.3', N'p26-oc1__fig-8-4-3-3__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/p26-oc1__fig-8-4-3-3__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-oc1__fig-8-4-3-3__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-oc1/p26-oc1__fig-8-4-3-3__grafica-analitica__diagnostico-contexto.png', 4096, 3335, N'9ad6dfd6b3397bc527ac91337a1426c459ae786ee28da9ebf9ab580a7bfc5367', N'leyenda y contexto textual del PAM');
