    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'P26-NT1'), N'P26-NT1', N'Incremento de transformación en la SE Durango Dos', N'rnt-ampliacion', N'Norte', 1, N'8.4.5.1', N'DIAGRAMA UNIFILAR DE LA ZONA DE INFLUENCIA', N'Diagrama unifilar técnico. DIAGRAMA UNIFILAR DE LA ZONA DE INFLUENCIA.', N'En la Figura 8.4.5.1. se presenta el diagrama unifilar simplificado de la zona de influencia, en este se observan las trayectorias de las Líneas de Transmisión, así como las Subestaciones Eléctricas de 230/115 kV que operan como fuente de suministro de la energía eléctrica a la Ciudad de Durango, Durango.', N'Diagrama unifilar técnico: DIAGRAMA UNIFILAR DE LA ZONA DE INFLUENCIA. Proyecto P26-NT1: Incremento de transformación en la SE Durango Dos.', N'unifilar-tecnico', N'Diagrama unifilar técnico', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:P26-NT1:FIG-8.4.5.1', N'p26-nt1__fig-8-4-5-1__unifilar-tecnico__diagnostico-contexto.png', N'pam2026-2040/p26-nt1__fig-8-4-5-1__unifilar-tecnico__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/p26-nt1__fig-8-4-5-1__unifilar-tecnico__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/p26-nt1/p26-nt1__fig-8-4-5-1__unifilar-tecnico__diagnostico-contexto.png', 4096, 1698, N'ccd74dc7225195f53c257c614a46f4db5ab97a3b06871b92207546109aa72a72', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
