    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 2, N'8.4.6.2', N'Curva de demanda horaria y de carga de las Zonas de distribución Villahermosa, Chontalpa y Los Ríos en 2025', N'Gráfica analítica. Curva de demanda horaria y de carga de las Zonas de distribución Villahermosa, Chontalpa y Los Ríos en 2025.', N'En la figura 8.4.6.2 se presenta la curva horaria de la demanda histórica de 2025 donde se puede observar que la demanda de las Zonas Villahermosa, Chontalpa y Los Ríos tuvo puntos operativos con valores superiores a 1,030 MWh/h desde abril hasta octubre, con punto máximo de 1,475 MWh/h el 27 de mayo a las 22 hrs.', N'Gráfica analítica: Curva de demanda horaria y de carga de las Zonas de distribución Villahermosa, Chontalpa y Los Ríos en 2025. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.2', N'i26-pe1__fig-8-4-6-2__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-2__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-2__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-2__grafica-analitica__diagnostico-contexto.png', 4096, 2153, N'8c8c0a950bc4ca72858385d5302cfc25e35fc6058e7ad182396819018f5bff8f', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 3, N'8.4.6.3', N'PRonóstico de la demanda del estado de tabasco', N'Gráfica analítica. PRonóstico de la demanda del estado de tabasco.', N'De acuerdo con el Pronóstico de Demanda por Subestaciones 2026-2046 en su escenario de Planeación, se estima un crecimiento de 1.9% de la demanda hasta 2030 y de 2030 al horizonte de 2046 se tendrá un crecimiento estimado de 1.8%. En la Figura 8.4.6.3 se muestra la gráfica de pronóstico de demanda para las zonas Villahermosa, Chontalpa y Los Ríos (Estado de Tabasco) en la demanda máxima coincidente de Gerencia.', N'Gráfica analítica: PRonóstico de la demanda del estado de tabasco. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.3', N'i26-pe1__fig-8-4-6-3__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-3__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-3__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-3__grafica-analitica__diagnostico-contexto.png', 4096, 2977, N'4da1484c581ef07de218487356feb225bfd6f0ce6d1b924b0da5a6197588b424', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 4, N'8.4.6.4', N'registro histórico de flujo de potencia por la compuerta grijalva - tabasco', N'Gráfica analítica. registro histórico de flujo de potencia por la compuerta grijalva - tabasco.', N'Por la importancia que tiene esta compuerta de flujo para la atención de la demanda en los estados de Tabasco, Campeche, Yucatán y Quintana Roo se ha evaluado de manera detallada por parte de CENACE los límites de transmisión en esta compuerta considerando la infraestructura eléctrica, definiendo límite con EAR de 1,620 MW y límite normal sin EAR de 1,150 MW. En la Figura 8.4.6.4 se muestra el registro histórico de 2025 del flujo de potencia por la compuerta Grijalva – Tabasco, en donde se observa que se ha rebasado durante 8 horas el límite de transmisión con EAR.', N'Gráfica analítica: registro histórico de flujo de potencia por la compuerta grijalva - tabasco. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.4', N'i26-pe1__fig-8-4-6-4__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-4__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-4__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-4__grafica-analitica__diagnostico-contexto.png', 4096, 2179, N'273ce5d43073b392ede886e1ab2792643b08b4bd9731bcefc176194dbfb234c9', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 5, N'8.4.6.5', N'Curva de demanda horaria y de carga de la gcr peninsular en 2025', N'Gráfica analítica. Curva de demanda horaria y de carga de la gcr peninsular en 2025.', N'Como se ha mencionado previamente la GCR Peninsular abarca como región geográfica dos estados de la República Mexicana con mayor dinamismo en crecimiento a nivel nacional, en la Figura 8.4.6.5 se muestra la curva horaria de la demanda histórica de 2025, donde se puede observar que la demanda de la GCR Peninsular tuvo puntos operativos con valores superiores a 2162 MWh/h desde Febrero hasta Noviembre, con punto máximo de 2,921 MWh/h el 27 de mayo a las 22 hrs.', N'Gráfica analítica: Curva de demanda horaria y de carga de la gcr peninsular en 2025. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.5', N'i26-pe1__fig-8-4-6-5__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-5__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-5__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-5__grafica-analitica__diagnostico-contexto.png', 4096, 2152, N'ec1148f95d544cf7ee2add9c98d6fd5f423f793a2485950d02aec151d34f86d2', N'leyenda y contexto textual del PAM');
