    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 8, N'8.4.6.8', N'registro histórico de flujo de potencia por la compuerta Escárcega - sur', N'Gráfica analítica. registro histórico de flujo de potencia por la compuerta Escárcega - sur.', N'La Gerencia de Control Regional Peninsular se interconecta al Sistema Eléctrico Nacional a través de cuatro circuitos; dos en 400 kV entre las Subestaciones Eléctricas Tabasco Potencia y Escárcega Potencia, además de dos circuitos en 230 kV entre las SE Macuspana II/Los Ríos y Santa Lucía. A este enlace se le conoce como compuerta de flujo Escarcega – Sur, actualmente se ha definido un límite de transmisión con EAR de 1,365 MW el cual en 2025 se han registrado valores muy cercanos a su límite, esto se muestra en la Figura 8.4.6.8.', N'Gráfica analítica: registro histórico de flujo de potencia por la compuerta Escárcega - sur. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.8', N'i26-pe1__fig-8-4-6-8__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-8__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-8__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-8__grafica-analitica__diagnostico-contexto.png', 4096, 2044, N'f151743966ae0a5f1a60372a5195a8075e34fad9d7f7af50f117bd6aa09ee582', N'leyenda y contexto textual del PAM');
    INSERT INTO dgmesnie.PAMProyectoImagen
    (ProyectoId, ClaveProyecto, ProyectoNombrePAM, Familia, GCR, OrdenImagen, FiguraNumeroPAM, FiguraTituloPAM, DescripcionImagen, ContextoPAM, TextoAlternativo, TipoImagenCodigo, TipoImagenDescripcion, Variante, TipoRelacion, EsCompartida, AssetId, NombreArchivo, RutaCDN, UrlCDN, RutaOrigenPaquete, AnchoPx, AltoPx, Sha256, FuenteDescripcion)
    VALUES
    ((SELECT TOP 1 ProyectoId FROM dgmesnie.vw_PAMProyectoVigente WHERE ClaveProyecto = N'I26-PE1'), N'I26-PE1', N'Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo', N'rnt-ampliacion', N'Peninsular Oriental', 9, N'8.4.6.9', N'registro histórico de flujo de potencia por la compuerta valladolid - Cancún', N'Gráfica analítica. registro histórico de flujo de potencia por la compuerta valladolid - Cancún.', N'La red eléctrica hacia la Península de Yucatán es longitudinal desde el punto de conexión con la GCR Oriental (enlaces del Grijalva), lo que provoca limitaciones para el suministro hasta el punto extremo de conexión que corresponde a las zonas de distribución de mayor carga siendo Cancún y Riviera Maya. Otra compuerta de flujo de gran importancia corresponde al Valladolid – Cancún que consta de dos circuitos en 400 kV que unen a las SE Dzitnup y Riviera Maya, dos circuitos en 230 kV entre las SE Valladolid y Nizuc/Balam y tres circuitos en 115 kV entre las SE Tizimín – Popolnáh, Valladolid – Chemax y Valladolid – Tulum. Los límites de transmisión con EAR corresponde a 1,180 MW. En Figura 8.4.6.9 se muestra el registro histórico de 2025 del flujo de potencia, en donde se observa que actualmente se opera con flujos de energía muy cercanos a su límite.', N'Gráfica analítica: registro histórico de flujo de potencia por la compuerta valladolid - Cancún. Proyecto I26-PE1: Suministro de energía eléctrica para los estados de Tabasco, Campeche, Yucatán y Quintana Roo.', N'grafica-analitica', N'Gráfica analítica', N'diagnostico-contexto', N'dedicada', 0, N'PAMRNT-2026-2040:I26-PE1:FIG-8.4.6.9', N'i26-pe1__fig-8-4-6-9__grafica-analitica__diagnostico-contexto.png', N'pam2026-2040/i26-pe1__fig-8-4-6-9__grafica-analitica__diagnostico-contexto.png', N'https://cdn.sassoapps.com/dgmesnie/pam/pam2026-2040/i26-pe1__fig-8-4-6-9__grafica-analitica__diagnostico-contexto.png', N'pamrnt/2026-2040/rnt-ampliacion/i26-pe1/i26-pe1__fig-8-4-6-9__grafica-analitica__diagnostico-contexto.png', 4096, 2243, N'd376fcccf11e3440071d75441e4cd32aa794780cb222c8a9976aadfadc683ed8', N'leyenda y contexto textual del PAM');
