SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;

BEGIN TRY
    BEGIN TRANSACTION;

    IF OBJECT_ID(N'dgmesnie.PAMProyectoImagen', N'U') IS NULL
    BEGIN
        CREATE TABLE dgmesnie.PAMProyectoImagen
        (
            ImagenId              BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PAMProyectoImagen PRIMARY KEY,
            ProyectoId            BIGINT NULL,
            ClaveProyecto         NVARCHAR(100) NOT NULL,
            ProyectoNombrePAM     NVARCHAR(500) NULL,
            Familia               NVARCHAR(100) NULL,
            GCR                   NVARCHAR(100) NULL,
            OrdenImagen           INT NOT NULL DEFAULT (1),
            FiguraNumeroPAM       NVARCHAR(50) NULL,
            FiguraTituloPAM       NVARCHAR(500) NULL,
            DescripcionImagen     NVARCHAR(MAX) NULL,
            ContextoPAM           NVARCHAR(MAX) NULL,
            TextoAlternativo      NVARCHAR(1000) NULL,
            TipoImagenCodigo      NVARCHAR(100) NULL,
            TipoImagenDescripcion NVARCHAR(200) NULL,
            Variante              NVARCHAR(100) NULL,
            TipoRelacion          NVARCHAR(50) NULL,
            EsCompartida          BIT NOT NULL DEFAULT (0),
            AssetId               NVARCHAR(150) NULL,
            NombreArchivo         NVARCHAR(255) NULL,
            RutaCDN               NVARCHAR(500) NULL,
            UrlCDN                NVARCHAR(1000) NOT NULL,
            RutaOrigenPaquete     NVARCHAR(500) NULL,
            AnchoPx               INT NULL,
            AltoPx                INT NULL,
            Sha256                NVARCHAR(64) NULL,
            FuenteDescripcion     NVARCHAR(500) NULL,
            Activo                BIT NOT NULL DEFAULT (1),
            FechaRegistroUtc      DATETIME2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
            CONSTRAINT FK_PAMProyectoImagen_Proyecto FOREIGN KEY (ProyectoId) REFERENCES dgmesnie.PAMProyecto(ProyectoId)
        );

        CREATE INDEX IX_PAMProyectoImagen_Clave ON dgmesnie.PAMProyectoImagen(ClaveProyecto, Activo, OrdenImagen);
        CREATE INDEX IX_PAMProyectoImagen_Proyecto ON dgmesnie.PAMProyectoImagen(ProyectoId, Activo, OrdenImagen);
    END;

    -- Limpia datos previos si existen para recarga completa
    DELETE FROM dgmesnie.PAMProyectoImagen;


    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

SELECT COUNT(*) AS TotalImagenesRegistradas FROM dgmesnie.PAMProyectoImagen;